def _orig_size_to_numpy(orig_size: Any) -> np.ndarray:
    """Convert `orig_size` to a numpy array. After passing through a `DataLoader`,
    it might be given as a list of `torch.Tensor`, in which case it should first be
    converted to a single `torch.Tensor` and then to a numpy array."""
    if isinstance(orig_size, (list, tuple)) and all(isinstance(o, torch.Tensor) for o in orig_size):
        orig_size = torch.stack([torch.as_tensor(o) for o in orig_size])
    return np.asarray(orig_size)


